// The PNGs are generated by scripts/artwork.ts. Imported as files so the bundler serves
// them as cacheable assets instead of inlining them into every page.
import clouds from "./artwork/clouds.png";
import contours from "./artwork/contours.png";
import maskDown from "./artwork/mask-down.png";
import maskLeft from "./artwork/mask-left.png";
import maskRight from "./artwork/mask-right.png";
import maskUp from "./artwork/mask-up.png";
import primaryContours from "./artwork/primary-contours.png";

/** Next.js imports images as `{ src }`; other bundlers give the URL itself. */
const url = (asset: string | { src: string }) =>
  typeof asset === "string" ? asset : asset.src;

export const contourArtwork = url(contours);
export const primaryContourArtwork = url(primaryContours);
export const cloudArtwork = url(clouds);
export const contourMasks = {
  up: url(maskUp),
  down: url(maskDown),
  left: url(maskLeft),
  right: url(maskRight),
} as const;
